def _import_fetchart(self):
    # Provide dummy modules to satisfy imports in beets/beetsplug
    if "confuse" not in sys.modules:
        sys.modules["confuse"] = MagicMock()
    if "requests" not in sys.modules:
        sys.modules["requests"] = MagicMock()
    if "mediafile" not in sys.modules:
        mediafile_mock = MagicMock()
        # image_mime_type is used; make it return a supported type
        mediafile_mock.image_mime_type.return_value = "image/png"
        sys.modules["mediafile"] = mediafile_mock
    import importlib
    return importlib.import_module("beetsplug.fetchart")
